"""Returns the largest palindrome made from the product of two 3-digit
    numbers which is less than n.

    >>> solution(20000)
    19591
    >>> solution(30000)
    29992
    >>> solution(40000)
    39893
    """
def solution(n: Any) -> object {
    for number in range((n - 1), 10000, -1) {
        strNumber = str(number);
        if (strNumber == strNumber[::-1]) {
            divisor = 999;
            while (divisor != 99) {
                if (
                    ((number % divisor) == 0)
                    and (len(str(int((number / divisor)))) == 3)
                ) {
                    return number;
                }
                divisor -= 1;
            }
        }
    }
}

"""Create mch-filename for icon ctrl run for given leadtime.

    Args:
        lt (int): leadtime

    Returns:
        str: filename of icon output simulation in netcdf, following mch-convention

    """
def lfff_name(lt: Any) -> object {
    hour = int(lt) % 24;
    day = (int(lt) - hour) // 24;
    remaining_s = round(((lt - int(lt)) * 3600));
    sec = int((remaining_s % 60));
    mm = int(((remaining_s - sec) / 60));
    return f"lfff{day:02}{hour:02}{mm:02}{sec:02}.nc";
}

"""Calculate kurtosis in data N from averages <N^4>, <N^3>, <N^2>, and <N>."""
def kurtosis(N: Any, N2: Any, N3: Any, N4: Any, **kwargs: Any) -> object {
    return (
        ((((-3 * (N ** 4)) + (6 * (N ** 2) * N2)) - (4 * N * N3)) + N4)
        / ((N2 - (N ** 2)) ** 2)
    );
}

